var ConMod = this.getField("Con Mod");
var HD = this.getField("HD1 Level");

if (HD.value !== "") {
	event.value = ConMod.value
} else {
	event.value = ""
};

var ConMod = this.getField("Con Mod")
var HD = this.getField("HD2 Level")

if (HD.value != "") {
event.value = ConMod.value
}
else
event.value = ""

var ConMod = this.getField("Con Mod")
var HD = this.getField("HD3 Level")

if (HD.value != "") {
event.value = ConMod.value
}
else
event.value = ""

var outcome = "";
if(isNaN(event.value) && event.value.indexOf(",") !== -1) {
	outcome = event.value.replace(",", ".") * 1
};
if(isNaN(outcome) || outcome < 0){event.rc=false};

var LbKg = What("Unit System") === "imperial";
var spans = new Array();
spans[0] = new Object();
spans[0].text = LbKg ? "LB" : "K";
spans[0].textSize = 7;
spans[0].alignment = "center";
spans[1] = new Object();
spans[1].text = LbKg ? "S" : "G";
spans[1].textSize = 4.9;
spans[1].alignment = "center";
event.richValue = spans;

this.delay = true;
this.calculate = false;

var LeftRight = "";
if (event.target.name.substring(0, 8) === "AmmoLeft") {
	LeftRight = "AmmoLeft";
} else if (event.target.name.substring(0, 9) === "AmmoRight") {
	LeftRight = "AmmoRight";
}
var theAmount = LeftRight + "Display.Amount";
if (LeftRight) {
	var current = LeftRight + "Display.CurrentAmount"
	
	if (event.target.isBoxChecked(0) === 1 && this.getField(theAmount).value > 0) {
		this.getField(theAmount).value -= 1;
		this.getField(current).value -= 1;
	} else if (event.target.isBoxChecked(0) === 0) {
		this.getField(theAmount).value += 1;
		this.getField(current).value += 1;
	}
	
	if (What(theAmount) < What(LeftRight + "Display.MaxAmount") && What(LeftRight + "Display.SaveAmount") <= What(LeftRight + "Display.MaxAmount")) {
		LoadAmmo();
	} else if (What(current) < What(LeftRight + "Display.MaxAmount")) {
		LoadAmmo(What(current));
	}
}

this.calculate = IsNotReset;
this.delay = false;
if (IsNotReset) {
	this.calculateNow()
};

var FtM = What("Unit System") === "imperial";
var spans = new Array();
spans[0] = new Object();
spans[0].text = FtM ? "10" : "3";
spans[0].textSize = 6;
spans[1] = new Object();
spans[1].text = FtM ? " FT" : " M";
spans[1].textSize = 4.2;
spans[2] = new Object();
spans[2].text = " S";
spans[2].textSize = 6;
spans[3] = new Object();
spans[3].text = "PEED";
spans[3].textSize = 4.2;
event.richValue = spans;

var FtM = What("Unit System") === "imperial";
var spans = new Array();
spans[0] = new Object();
spans[0].text = FtM ? "20" : "6";
spans[0].textSize = 6;
spans[1] = new Object();
spans[1].text = FtM ? " FT" : " M";
spans[1].textSize = 4.2;
spans[2] = new Object();
spans[2].text = " S";
spans[2].textSize = 6;
spans[3] = new Object();
spans[3].text = "PEED";
spans[3].textSize = 4.2;
event.richValue = spans;

var FtM = What("Unit System") === "imperial";
var decSep = What("Decimal Separator") === "comma" ? "," : ".";
var spans = new Array();
spans[0] = new Object();
spans[0].text = FtM ? "5" : "1" + decSep + "5";
spans[0].textSize = 6;
spans[1] = new Object();
spans[1].text = FtM ? " FT" : " M";
spans[1].textSize = 4.2;
event.richValue = spans;

if (event.value) {
	Checkbox("Proficiency Armor Other");
} else {
	Checkbox("Proficiency Armor Other", false);
}

